#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=C4 bundle=control
#pragma HLS INTERFACE s_axilite port=sum bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int nr = NR;
    const int nq = NQ;
    const int np = NP;

  int r, q, p, s;

  // ---------------------------------------------------------------
  // Local staging buffers (fixed size from macros).
  //   C4_local : full weight matrix, reused across every (r,q) row.
  //   sum_local: final output vector.
  // A is processed one (r,q) row at a time via a small tile buffer.
  // ---------------------------------------------------------------
  static double C4_local[NP][NP];
  static double sum_local[NP];

  // Per-row tile buffers (one row = NP contiguous elements).
  double in_tile[NP];
  double out_tile[NP];

  // Partition C4_local on BOTH dims:
  //   dim=1 (s index): feeds the fully-unrolled REDUCE_S reduction.
  //   dim=2 (p index): feeds the unrolled COMPUTE_P lanes so each
  //                    parallel p-lane can read its own column.
  // in_tile is complete-partitioned so every unrolled lane can read
  // all NP reduction operands in parallel.
#pragma HLS ARRAY_PARTITION variable=C4_local complete dim=1
#pragma HLS ARRAY_PARTITION variable=C4_local cyclic factor=2 dim=2
#pragma HLS ARRAY_PARTITION variable=in_tile  complete dim=1
#pragma HLS ARRAY_PARTITION variable=out_tile cyclic factor=2 dim=1

  // ------------------------- LOAD (C4) ---------------------------
  // Stage the full weight matrix once (contiguous, burst-friendly).
  LOAD_C4_R: for (p = 0; p < np; p++)
    LOAD_C4_C: for (s = 0; s < np; s++) {
#pragma HLS PIPELINE II=1
      C4_local[p][s] = C4[p][s];
    }

  // ---------------- TILED LOAD / COMPUTE / STORE -----------------
  // Iterate over each (r,q) row. For each row:
  //   1. LOAD  the row A[r][q][*] into in_tile.
  //   2. COMPUTE the matrix-vector product into out_tile.
  //   3. STORE out_tile back into A[r][q][*] (and sum on the last row).
  TILE_R: for (r = 0; r < nr; r++) {
    TILE_Q: for (q = 0; q < nq; q++) {

      bool is_last = (r == nr - 1) && (q == nq - 1);

      // --- LOAD phase: bring one row into the local tile buffer ---
      LOAD_ROW: for (p = 0; p < np; p++) {
#pragma HLS PIPELINE II=1
        in_tile[p] = A[r][q][p];
      }

