      // Unroll the independent p-dimension by 2 so two output columns
      // are computed per pipeline iteration. Each p-lane performs its
      // own reduction over s using the fully-unrolled REDUCE_S loop.
      COMPUTE_P: for (p = 0; p < np; p += 2) {
#pragma HLS PIPELINE II=1
        LANE_P: for (int lane = 0; lane < 2; lane++) {
