          int pp = p + lane;
          double acc = 0.0;
          REDUCE_S: for (s = 0; s < np; s++) {
#pragma HLS UNROLL
            acc += in_tile[s] * C4_local[s][pp];
          }
          out_tile[pp] = acc;
        }
      }

      // --- STORE phase: write the computed row back to global memory ---
      STORE_ROW: for (p = 0; p < np; p++) {
#pragma HLS PIPELINE II=1
        double v = out_tile[p];
        A[r][q][p] = v;
        if (is_last) sum_local[p] = v;
      }
    }
  }

  // ------------------------- STORE (sum) -------------------------
  STORE_SUM: for (p = 0; p < np; p++) {
#pragma HLS PIPELINE II=1
    sum[p] = sum_local[p];
  }

}
